import {cooperationAllies} from './growth-cooperation.js';
import {countryValue} from './research.js';
import {ACTION_CARDS} from './basic-actions.js';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const name=(id,cards)=>cards[id]?.name||ACTION_CARDS[id]?.name||'能力牌';
export function renderCooperation(s,id,cards){return `<section class="flow-panel"><b>盟国合作 · 每轮一次 · 仅行动阶段</b><p>横置一个盟国，查看等于其价值的牌，选1张加入手牌，其余按所选顺序放回牌库顶。牌库不足时洗入弃牌，尽量补足。</p><label>横置盟国<select id="growth-ally">${cooperationAllies(s).map(cid=>`<option value="${cid}">${esc(cards[cid]?.name||'盟国')} · 查看${countryValue(cid)}张</option>`).join('')}</select></label><button data-card-action="useGrowthAbility" data-id="${id}">横置盟国并查看</button></section>`;}
function orderFields(pending,keep,cards){const remaining=pending.inspected.filter(id=>id!==keep);return remaining.length?`<p>放回顺序从牌堆顶向下排列：</p>${remaining.map((id,index)=>`<label>牌堆顶第${index+1}张<select data-growth-order="${index}">${remaining.map(cid=>`<option value="${cid}" ${cid===id?'selected':''}>${esc(name(cid,cards))}</option>`).join('')}</select></label>`).join('')}`:'<p>没有剩余牌需要放回。</p>';}
export function renderCooperationPending(s,cards){const pending=s.flow.pendingGrowth;return `<b>盟国合作 · 选择保留牌和放回顺序</b><p>已横置盟国并查看${pending.inspected.length}张。候选仅本人可见，选择完成前暂停其他操作。</p><div class="growth-choice-grid">${pending.inspected.map((id,i)=>`<label class="growth-choice"><img src="${esc(cards[id]?.image||'')}" alt="${esc(name(id,cards))}"><span><input type="radio" name="growth-keep" data-growth-keep="${id}" ${i===0?'checked':''}> 保留${esc(name(id,cards))}</span></label>`).join('')}</div><div id="growth-return-order">${orderFields(pending,pending.inspected[0],cards)}</div><button id="finish-growth-choice">确认保留与放回顺序</button>`;}
export function updateCooperationOrder(s,cards){const keep=document.querySelector('[data-growth-keep]:checked')?.dataset.growthKeep,target=document.querySelector('#growth-return-order');if(target&&s.flow?.pendingGrowth?.effect==='cooperation')target.innerHTML=orderFields(s.flow.pendingGrowth,keep,cards);}
